function today() {
  var d = new Date(); function p(x) { return (x < 10 ? "0" : "") + x; }
  return d.getFullYear() + "-" + p(d.getMonth() + 1) + "-" + p(d.getDate());
}
// stamp build date (both scripts) + enabled-features line (server only)
function stampHeader(s, cfg) {
  s = s.replace(/built: \d{4}-\d{2}-\d{2}/, "built: " + today());
  var m = (cfg && cfg.mods) || {};
  var feats = [];
  for (var i = 0; i < MODULES.length; i++) {
    var mod = MODULES[i], t = TAGS[mod.key];
    if (!t) continue;
    if (mod.core || m[mod.key] !== false) feats.push(t);
  }
  return s.replace(/(#   features: ).*/, "$1" + feats.join(" · "));
}

// ── helpers ──
function ksAcc(arr, fb) {
  var a = (arr || []).map(function (x) { return String(x).trim(); }).filter(Boolean);
  if (!a.length && fb) a = [fb];
  return a.map(function (x) { return '"' + x.replace(/["\\]/g, "") + '"'; }).join(", ");
}
function n(v, d) { var x = parseFloat(v); return isNaN(x) ? d : x; }
function setNum(s, name, val) { return s.replace(new RegExp("(\\bnum\\s+" + name + "\\s*=\\s*)[-0-9.]+"), "$1" + val); }
function setStr(s, name, val) { return s.replace(new RegExp("(\\bstr\\s+" + name + "\\s*=\\s*)\"[^\"]*\""), '$1"' + String(val || "").replace(/["\\]/g, "") + '"'); }
function setBool(s, name, val) { return s.replace(new RegExp("(\\bbool\\s+" + name + "\\s*=\\s*)(?:true|false)"), "$1" + (val ? "true" : "false")); }
// append user-supplied raw KrunkScript to the END (top-level) of a generated script. Raw concat
// (NOT setStr) — this is code, not a string literal. No-op when the box is empty/whitespace.
function appendCustom(s, code) { var c = String(code || "").replace(/\r/g, ""); if (!c.replace(/\s/g, "")) { return s; } return s + "\n\n# ===== custom code (user-added) =====\n" + c + "\n"; }
// apply every optional module's USE_<flag> from cfg.mods (default ON if unset)
function applyMods(s, cfg) {
  var m = (cfg && cfg.mods) || {};
  for (var i = 0; i < MODULES.length; i++) {
    var mod = MODULES[i];
    if (!mod.flag) continue;
    var on = (m[mod.key] !== false);   // default true
    s = setBool(s, "USE_" + mod.flag, on);
  }
  return s;
}

// map of FLAG -> on/off from the checkboxes (default on)
function activeFlags(cfg) {
  var m = (cfg && cfg.mods) || {}, on = {};
  for (var i = 0; i < MODULES.length; i++) {
    if (!MODULES[i].flag) continue;
    on[MODULES[i].flag] = (m[MODULES[i].key] !== false);
  }
  return on;
}
// Physically REMOVE the code of unselected features. Regions are delimited in the
// templates by `#@F:FLAG[,FLAG2]` ... `#@E` (a region is kept if ANY of its flags
// is on; regions nest). Lines outside any region are shared base, always kept.
function strip(s, on) {
  var lines = s.split("\n"), out = [], stack = [];
  for (var i = 0; i < lines.length; i++) {
    var t = lines[i].replace(/^\s+/, "");
    if (t.indexOf("#@F:") === 0) {
      var fl = t.slice(4).split(",").map(function (x) { return x.trim(); }).filter(Boolean);
      var keep = false;
      for (var f = 0; f < fl.length; f++) { if (on[fl[f]]) { keep = true; } }
      stack.push(keep);
      continue;
    }
    if (t.indexOf("#@E") === 0) { stack.pop(); continue; }
    var drop = false;
    for (var k = 0; k < stack.length; k++) { if (!stack[k]) { drop = true; } }
    if (!drop) { out.push(lines[i]); }
  }
  // collapse 3+ blank lines left by stripping down to one
  return out.join("\n").replace(/\n{3,}/g, "\n\n");
}

// Quote-aware comment stripper for the SHIPPED client script (anti-rip): removes every `#`
// comment that is OUTSIDE a string, so a ripped client.txt carries no explanatory text. Color
// literals like "#ff5d7a" are preserved (the `#` there sits inside a string). Runs AFTER strip()
// so no `#@F/#@E` markers remain. Drops emptied lines + collapses blank runs.
function stripComments(s) {
  var lines = s.split("\n"), out = [];
  for (var i = 0; i < lines.length; i++) {
    var line = lines[i], inStr = false, cut = -1;
    for (var c = 0; c < line.length; c++) {
      var ch = line[c];
      if (ch === '"' && line[c - 1] !== "\\") { inStr = !inStr; }
      else if (ch === "#" && !inStr) { cut = c; break; }
    }
    if (cut >= 0) { line = line.slice(0, cut).replace(/\s+$/, ""); }
    if (line.replace(/\s/g, "").length > 0) { out.push(line); }
  }
  return out.join("\n");
}

